style.css:
@-moz-document domain("avito.ru") {
:root {
    color-scheme: dark;

    --av-bg: #14181d;          /* base canvas */
    --av-surface: #1c2128;     /* elevated cards */
    --av-surface-2: #1a1f26;   /* secondary surface */
    --av-header: #0d1117;      /* header / footer */
    --av-border: #2a313a;      /* subtle borders */
    --av-text: #e6edf3;        /* primary text */
    --av-text-soft: #c4cdd6;   /* body text */
    --av-text-muted: #8b949e;  /* muted / placeholder */
    --av-accent: #4aa8ff;      /* refined Avito blue */
    --av-accent-hover: #7cc4ff;
  }

  /* Base canvas */
  html {
    background-color: var(--av-bg) !important;
  }
  body {
    background-color: var(--av-bg) !important;
    color: var(--av-text-soft) !important;
  }

  /* Borders */
  /* Colour only, never adds a border, so it is safe to apply universally. */
  *, *::before, *::after {
    border-color: var(--av-border) !important;
  }

  /* Hashed, unstable class names: structural blocks go transparent and the real surfaces are
     re-painted below. `label` is in the list — Avito wraps inputs in a `<label>` carrying a hard
     white field background.
     `span` must NOT be added: spans carry Avito's data-driven fills (colour swatches, the
     current-page pill). The one light span, the avatar placeholder, is re-painted below. */
  div, section, article, main, aside, ul, ol, li, dl, dd, dt,
  table, tbody, thead, tr, td, th, figure, fieldset, label {
    background-color: transparent !important;
  }
  /* The one light SPAN: the avatar placeholder. The shared `-module-avatar` fragment covers every
     build's spelling. */
  [class*="-module-avatar"] span {
    background-color: var(--av-surface) !important;
  }
  /* The circle keeps a hard `#f2f1f0` while the broad text rule lightens its mask glyph. */
  [class*="ShowAllButton-module-circle"] {
    background-color: var(--av-surface) !important;
  }

  /* The DS inline icon paints its glyph from the inherited `color`, and it is a mask, so `color`
     moves it, not `fill`. */
  svg[data-icon-name="afblogo"] {
    color: #ff6163 !important;
  }

  /* The 2px `#ff6163` ring is the ONLY unread marker and the blanket border reset would collapse
     it; native hue clears 4.5:1. The marker scope keeps the short `bordered-` modifier from
     matching elsewhere. */
  [class*="preview-item-bordered"],
  [data-marker="story-previewer/block-preview"] [class*="bordered-"] {
    border-color: #ff6163 !important;
  }

  /* Header bar */
  [data-marker="header/navbar"],
  header {
    background-color: var(--av-header) !important;
    border-color: var(--av-border) !important;
  }
  /* The navbar is a DIV; real `<header>`s are inside popups and cards, which the bare `header`
     arm above would blacken. */
  [data-marker$="/popup-header"] {
    background-color: transparent !important;
  }
  /* Card PHOTO FRAMES are semantic `<header>`s, natively transparent, and show during lazy-load,
     behind transparent PNGs and in letterboxed gaps. The bare `header` arm must stay: the legacy
     404 template's page chrome is a real `<header class="header">`. */
  header[class*="picture"] {
    background-color: transparent !important;
  }
  /* Every `<header>` with a marker is a COMPONENT header, natively transparent; the legacy 404
     template's, which the bare arm exists for, has no marker. */
  header[data-marker] {
    background-color: transparent !important;
  }

  /* Sticky header + sort toolbar are hashed wrapper DIVs, not `<header>`, so the neutraliser
     flattens them and scrolled results bleed through. */
  [class*="stickyHeader"] {
    background-color: var(--av-header) !important;
    border-color: var(--av-border) !important;
  }
  /* The sort bar is a `position:sticky` DIV with a hard `#fff`; the `topPanel` family covers both
     spellings. CANVAS tone, not elevated: natively it is the same white as the page, so a surface
     tone would invent a stripe. */
  [class*="topPanel"] {
    background-color: var(--av-bg) !important;
    border-color: var(--av-border) !important;
  }
  /* The item page's `position:fixed` 48px title bar is natively WHITE and unreachable, but it
     carries a `transform`, so it is the containing block for `position:fixed` descendants and a
     pseudo hung inside it anchors to the bar's box. `.js-item-view-title-info` is the one non-hash
     class on the chain, and the marker also names the buy-box heart.
     The host node is load-bearing: `z-index:-1` resolves in the nearest STACKING CONTEXT, and the
     bar's price container is `z-index:15` while the favourite button is `z-index:auto`.
     The height is explicit rather than `bottom:0`, so losing the transform degrades this to a 48px
     strip and not a full-screen slab. */
  .js-item-view-title-info [data-marker="item-view/favorite-button"]::before {
    content: "";
    position: fixed;
    top: 0;
    height: 48px;
    left: 0;
    right: 0;
    z-index: -1;
    background-color: var(--av-header) !important;
  }
  /* The other gallery arm ships the 88px deep-scroll bar instead, under pure hashes: its white sits
     on a child whose `::before` spreads a 1280px white box-shadow to the viewport edges under a
     `clip-path: inset(0 -1280px)`. Neither is nameable, but this arm keeps the bar's title as an `h4`
     carrying the marker (the in-flow title and the 48px bar's are `h1`), so the pseudo hangs there
     and repeats the same shadow-and-clip trick over the white one: both are `z-index:-1` in the
     bar's stacking context and the deeper one paints last. Surface tone, not header: the bar's
     thumbnail and price/title are bare `<button>`s the generic button rule chips, and on a surface
     bar a surface chip is invisible should the hash below rotate. */
  h4[data-marker="item-view/title-info"]::before {
    content: "";
    position: fixed;
    top: 0;
    height: 88px;
    left: 0;
    right: 0;
    z-index: -1;
    background-color: var(--av-surface) !important;
    box-shadow: 0 0 0 1280px var(--av-surface) !important;
    clip-path: inset(0 -1280px);
  }
  button[class*="_6a9117bb1fcd1b61"] {
    background-color: transparent !important;
  }

  /* The wordmark path has NO fill attribute, so it defaults to black; `:not([fill])` keeps this off
     the coloured dot paths, which do carry fill attrs. Four builds name it differently — the last,
     the error/maintenance template, is class-less and marker-less, leaving its fixed brand viewBox
     as the only hook. */
  [class*="index-logo"] svg path:not([fill]),
  [class*="Logo-module"] svg path:not([fill]),
  a[href="/"] svg path:not([fill]),
  svg[viewBox="0 0 79 30"] path:not([fill]) {
    fill: var(--av-text) !important;
  }

  /* The hero-promo paints its gradient as background-IMAGE, which layers over background-color, so
     that must be cleared too. */
  [data-marker^="top-notification"],
  [data-marker^="top-banner"] {
    background-color: var(--av-surface-2) !important;
    background-image: none !important;
    border-color: var(--av-border) !important;
  }

  /* Inline-styled badges & pills */
  /* Fill arrives via an inline `background`, which the neutraliser would flatten. Each brand colour
     is refined to sit on the dark canvas. */

  /* NOTE ON CASE: Avito emits these inline styles as UPPERCASE hex, attribute matching is
     case-SENSITIVE, and the `i` flag is rejected by the userstyles.org parser — so every literal
     is listed in the exact case the site emits. */

  /* Ribbon end-caps, hex form. The cap's inline colour serialises as hex on some pages and `rgb()`
     on others, and must take the SAME tone as the pill body. Must precede the pill rules:
     "background-color:#02D15C" CONTAINS "color:#02D15C". */
  [style*="color:#02D15C"], [style*="color:#02d15c"] {
    color: #198049 !important;
  }
  [style*="color:#965EEB"], [style*="color:#965eeb"] {
    color: #7d5bc4 !important;
  }
  /* Red as INK, not fill: the badge-fill red is only ~3.3:1 on the canvas, so text takes a lighter
     step of the same hue. */
  [style*="color:#FF4053"], [style*="color:#ff4053"] {
    color: #ff5a6a !important;
  }
  [style*="color:#00AAFF"], [style*="color:#00aaff"] {
    color: var(--av-accent) !important;
  }
  [style*="color:#CCECFF"], [style*="color:#ccecff"],
  [style*="color:#CFEDFF"], [style*="color:#cfedff"],
  [style*="color: rgb(204, 236, 255)"], [style*="color:rgb(204, 236, 255)"],
  [style*="color: rgb(207, 237, 255)"], [style*="color:rgb(207, 237, 255)"] {
    color: #1d2c3a !important;
  }
  /* DISCOUNT ribbon ("Скидка"): body an inline `background-color:#E50965`, cap an inline
     `color:#E50965` on a `currentColor`-filled SVG path. */
  [style*="color:#E50965"], [style*="color:#e50965"],
  [style*="color: rgb(229, 9, 101)"], [style*="color:rgb(229, 9, 101)"] {
    color: #c41f66 !important;
  }
  /* The stock QUANTITY's inline `color: rgb(0, 194, 87)` is the only thing separating it from the
     "В наличии:" label, and the broad text rule's `!important` beats it; native #00c257 clears 7:1,
     so keep the hue. Listed with the cap rules because "background-color:#00C257" contains
     "color:#00C257", so anything painting that fill must come LATER. The descendant arm is required:
     the coloured span wraps an un-coloured span holding the text node. */
  [style*="color: rgb(0, 194, 87)"], [style*="color: rgb(0, 194, 87)"] *,
  [style*="color:rgb(0, 194, 87)"], [style*="color:rgb(0, 194, 87)"] *,
  [style*="color:#00C257"], [style*="color:#00C257"] *,
  [style*="color:#00c257"], [style*="color:#00c257"] * {
    color: #00c257 !important;
  }
  /* NEUTRAL ribbon: body is an inline `background-color:#EBEAE8`, cap an inline `color:#EBEAE8`
     on a `currentColor`-filled SVG path. */
  [style*="color:#EBEAE8"], [style*="color:#ebeae8"],
  [style*="color: rgb(235, 234, 232)"], [style*="color:rgb(235, 234, 232)"] {
    color: var(--av-surface) !important;
  }

  /* CRITICAL: these match inline `background-color:` ONLY. A bare `[style*="rgb(2, 209, 92)"]`
     also matches the ribbon END-CAPS, whose inline is `color: rgb(2, 209, 92)` on a
     `currentColor` path — it would paint them a solid rectangle and flip the tail white. */

  /* Light-blue info pills ("trusted seller", "documents verified"). */
  [style*="background-color: rgb(204, 236, 255)"],
  [style*="background-color:rgb(204, 236, 255)"],
  [style*="background-color: rgb(207, 237, 255)"],
  [style*="background-color:rgb(207, 237, 255)"],
  [style*="background-color:#ccecff"], [style*="background-color:#CCECFF"],
  [style*="background-color:#cfedff"], [style*="background-color:#CFEDFF"] {
    background-color: #1d2c3a !important;
    color: #9fd0f5 !important;
  }

  /* Sale / discount (red) */
  [style*="background-color: rgb(255, 64, 83)"],
  [style*="background-color:rgb(255, 64, 83)"],
  [style*="background-color:#ff4053"], [style*="background-color:#FF4053"] {
    background-color: #c8323f !important; color: #fff !important;
  }
  /* Below-market / delivery discount (green) */
  [style*="background-color: rgb(2, 209, 92)"],
  [style*="background-color:rgb(2, 209, 92)"],
  [style*="background-color:#02d15c"], [style*="background-color:#02D15C"] {
    background-color: #198049 !important; color: #fff !important;
  }
  /* Avito Guarantee / promo (purple) */
  [style*="background-color: rgb(150, 94, 235)"],
  [style*="background-color:rgb(150, 94, 235)"],
  [style*="background-color:#965eeb"], [style*="background-color:#965EEB"] {
    background-color: #7d5bc4 !important; color: #fff !important;
  }
  /* Installment / other brand-blue inline pills */
  [style*="background-color: rgb(0, 170, 255)"],
  [style*="background-color:rgb(0, 170, 255)"],
  [style*="background-color:#00aaff"], [style*="background-color:#00AAFF"] {
    background-color: var(--av-accent) !important; color: #0b1620 !important;
  }
  /* The score badge in the FIXED title bar sits under pure hashes; its only durable hook is the
     inline fill, written with the `background` SHORTHAND, which a `background-color:` selector
     cannot see. */
  [style*="background: rgb(0, 194, 87)"],
  [style*="background:rgb(0, 194, 87)"],
  [style*="background:#00C257"], [style*="background:#00c257"] {
    background-color: #198049 !important;
  }
  [style*="background: rgb(0, 194, 87)"],
  [style*="background: rgb(0, 194, 87)"] *,
  [style*="background:rgb(0, 194, 87)"],
  [style*="background:rgb(0, 194, 87)"] *,
  [style*="background:#00C257"], [style*="background:#00C257"] *,
  [style*="background:#00c257"], [style*="background:#00c257"] * {
    color: #fff !important;
  }
  /* Discount ribbon body — same ordering constraint as the neutral one below:
     "background-color:#E50965" CONTAINS "color:#E50965", so the cap rule must come first. */
  [style*="background-color:#E50965"], [style*="background-color:#e50965"],
  [style*="background-color: rgb(229, 9, 101)"],
  [style*="background-color:rgb(229, 9, 101)"] {
    background-color: #c41f66 !important; color: #fff !important;
  }
  /* Neutral ribbon body — must follow the `color:#EBEAE8` cap rule, because
     "background-color:#EBEAE8" CONTAINS "color:#EBEAE8". Avito emits the value as raw hex when
     server-rendered and as `rgb(...)` after a client re-render, so both spellings are listed. */
  [style*="background-color:#EBEAE8"], [style*="background-color:#ebeae8"],
  [style*="background-color: rgb(235, 234, 232)"],
  [style*="background-color:rgb(235, 234, 232)"] {
    background-color: var(--av-surface) !important;
    color: var(--av-text-soft) !important;
  }

  /* Ribbon end-caps: inline `color: rgb(<brand>)` on an SVG path with `fill: currentColor`, so
     the cap must take the SAME refined tone as the pill body above. */
  [style*="color: rgb(2, 209, 92)"], [style*="color: rgb(2, 209, 92)"] *,
  [style*="color:rgb(2, 209, 92)"], [style*="color:rgb(2, 209, 92)"] * {
    color: #198049 !important;
  }
  [style*="color: rgb(150, 94, 235)"], [style*="color: rgb(150, 94, 235)"] *,
  [style*="color:rgb(150, 94, 235)"], [style*="color:rgb(150, 94, 235)"] * {
    color: #7d5bc4 !important;
  }
  [style*="color: rgb(255, 64, 83)"], [style*="color: rgb(255, 64, 83)"] *,
  [style*="color:rgb(255, 64, 83)"], [style*="color:rgb(255, 64, 83)"] * {
    color: #ff5a6a !important;
  }
  [style*="color: rgb(0, 170, 255)"], [style*="color: rgb(0, 170, 255)"] *,
  [style*="color:rgb(0, 170, 255)"], [style*="color:rgb(0, 170, 255)"] * {
    color: var(--av-accent) !important;
  }
  /* One card build draws the end-cap as an EMPTY div filled from that same inline colour through
     `currentColor`, and the div-neutraliser wipes it, leaving the pill a flat rectangle. The cap
     rules above have already moved the colour to the pill's tone, so `currentColor` is the right
     fill. The card scope and `:empty` keep this off any text-bearing div with an inline colour. */
  [data-marker="item"] div[style^="color:"]:empty,
  [data-marker^="iva-item"] div[style^="color:"]:empty {
    background-color: currentColor !important;
  }

  /* Buttons */
  /* One hashed Button class serves both primary and secondary, so every button gets a dark surface
     and the real primary CTAs are promoted by data-marker.
     The `-button/link` arm must stay narrow: a bare `[data-marker$="/link"]` also catches
     `seller-link/link`, a transparent text link. `[role="button"]` is NOT matched — Avito hangs it
     on carousel SLIDES and rating STARS, all natively transparent.
     `[data-marker$="-button"]` is broad on purpose: `:not(a)` would raise it to (0,1,1) and beat the
     (0,1,0) brand-blue CTA rule below; the anchors it over-reaches are un-painted below. */
  button,
  a[class*="styles-module-root"], label[class*="styles-module-root"],
  [class*="multiselect-outline-input"], [class*="style-module-wrapper"],
  [class*="wrapper_variant_"],
  [data-marker$="-button"], [data-marker$="-button/link"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* `-button` is also on plain text LINKS, natively transparent `<a>`s. Every `-button` with a real
     light fill, and every brand-blue CTA, is a `<button>`; anchor CTAs come from the `-button/link`
     and `styles-module-root` arms. */
  a[data-marker$="-button"] {
    background-color: transparent !important;
  }
  /* Same over-reach on the DIV side, where `-button` names a hit ZONE. Every such div is natively
     transparent and already flattened, so un-painting can never leak a light surface.
     The carousels' scroll arrows are the same zone shipped as real `<button>`s, and the marker
     belongs to the CALL SITE: the `/all/<category>` hubs' rail ships the identical button with no
     marker and only its hashed module class, so the class hook is required alongside the markers. */
  div[data-marker$="-button"],
  [data-marker$="/scroll-button-back"],
  [data-marker$="/scroll-button-forward"],
  button[class*="scrollButton"] {
    background-color: transparent !important;
  }
  /* The pagination is a `<ul data-marker="pagination-button">`, so the suffix boxes the whole
     strip; the `<ul>` is natively transparent and only the current-page pill has a fill. The
     current-page rule below is (0,2,0) on the page element, so this cannot touch it. */
  ul[data-marker$="-button"] {
    background-color: transparent !important;
  }
  /* Its prev/next arrows are marker-less `<button>`s, natively transparent like the page numbers.
     Only the current page may carry a fill. */
  [data-marker="pagination-button"] button {
    background-color: transparent !important;
  }
  /* DS CHECKBOX and SWITCH labels are matched by the button rule's
     `label[class*="styles-module-root"]` arm but natively paint nothing — the class only declares a
     hover TOKEN. The Input labels that arm exists for carry `root_size-*` / `root_empty` /
     `root_preset_overlay` instead. The trailing hyphen discriminates: `root_preset_default-`
     excludes the Button's `root_preset_default_priority_primary-`. Same specificity (0,1,1), so
     source order un-paints these. */
  label[data-marker*="/checkbox/"],
  label[class*="styles-module-root_preset_default-"] {
    background-color: transparent !important;
  }
  /* Each gallery hit zone holds a real `<button>` the generic rule would box; the whole
     `image-frame/` family is overlay chrome on the picture and none of it may carry a surface. The
     lightbox's buy CTAs sit outside this prefix and keep their fills. */
  [data-marker^="image-frame/"] button,
  [data-marker^="extended-gallery-frame/"] button {
    background-color: transparent !important;
  }
  /* The rebuilt gallery drops the `image-frame/` markers: slides, hit zones, thumbnails and the
     lightbox close are all natively transparent `<button>`s under pure hashes, so the gallery marker
     is the one durable scope. */
  [data-marker="item-view/main-gallery"] button {
    background-color: transparent !important;
  }
  /* The buy-box heart is natively bare. The FIXED title bar's copy of the same marker IS a light
     `#f2f1f0` chip and hosts the bar's background pseudo, so it must keep a fill;
     `.js-item-view-title-info` separates them. */
  [data-marker="item-view/favorite-button"] {
    background-color: transparent !important;
  }
  .js-item-view-title-info [data-marker="item-view/favorite-button"] {
    background-color: var(--av-surface) !important;
  }
  /* Seller-profile badge rows and "Показать все" are natively transparent `<button>`s, only 230px
     wide while their labels run longer. */
  [data-marker^="badge-row-"],
  [data-marker="badge-show-all"] {
    background-color: transparent !important;
  }
  /* Natively transparent 16x156 `<button>`s floating ON the photo strip; a surface slices a band
     out of the end photos. */
  [class*="Carousel-module-arrow"] {
    background-color: transparent !important;
  }
  /* The DS LINK shares the `styles-module-root-...` prefix with the Button. Its own
     `root_underlineOffset_size-*` modifier is on links and never on buttons, and every element
     carrying it is natively transparent. Same specificity as the button arm, so source order
     un-paints them. */
  a[class*="root_underlineOffset"] {
    background-color: transparent !important;
  }
  /* The DS Button encodes hierarchy in its preset/priority modifier: PRIMARY is near-black
     `#141414`, secondary light `#f2f1f0`. Painted alike they are indistinguishable, and inside a
     floating panel (also `--av-surface`) both lose their button shape. Marker-specific rules below
     are later in source order, so per-CTA tuning still wins.
     The primary arm is scoped to `button`: the same preset lands on SEO tag ANCHORS, already claimed
     by the (0,1,1) `a[class*="styles-module-root"]` arm, so a (0,1,0) rule would win the label but
     lose the fill. */
  button[class*="root_preset_default_priority_primary"],
  button[class*="root_preset_primary"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  button[class*="root_preset_default_priority_primary"],
  button[class*="root_preset_default_priority_primary"] *,
  button[class*="root_preset_primary"],
  button[class*="root_preset_primary"] * {
    color: #0b1620 !important;
  }
  [class*="root_preset_secondary"] {
    background-color: #262c35 !important;
  }
  /* The suggest panel's refinement bubbles are secondary DS Buttons that the item-page build ships
     under pure hashes; the group's inline `--module-bubbleGroup-*` tokens are its only stable hook.
     Secondary tone, not surface: the panel is itself `--av-surface`, so a surface chip has no edge. */
  [style*="--module-bubbleGroup"] button {
    background-color: #262c35 !important;
  }
  /* One build drops the preset NAME and ships pure hashes, and a marker-less `<a>` build is
     unnameable here; every build resolves the fill through the same token, so remap the token rather
     than chase hashes. The site declares it on class-scoped theme containers, not `:root`, so a
     `:root` override would never be reached — the tag+attribute pair is what outranks them. Hover
     and pressed must move with it: this theme paints no `!important` fill here to mask a light one. */
  html [class] {
    --theme-semantics-components-button-bg-secondary: #1c2128;
    --theme-semantics-components-button-bg-secondaryHover: #262c35;
    --theme-semantics-components-button-bg-secondaryPressed: #2a313a;
    --theme-semantics-components-button-text-secondary: #e6edf3;
  }
  /* `root_preset_overlay` is the DS's float-over-imagery button, a solid WHITE pill; the generic
     surface would sink it to the tone of the panels it sits on. */
  [class*="root_preset_overlay"] {
    background-color: #262c35 !important;
  }
  /* `root_preset_accent` is the DS's OTHER solid primary; the region picker's main CTA carries no
     marker and would fall to the dark surface on a panel of the same tone. The trailing hyphen is
     load-bearing: it excludes the soft-blue `root_preset_accentSecondary-...` the block below
     re-tunes, and a build dropping the hash suffix simply restores today's grey. Scoped to `button`:
     anchors are already claimed by the (0,1,1) `a[class*="styles-module-root"]` arm. */
  button[class*="root_preset_accent-"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  button[class*="root_preset_accent-"],
  button[class*="root_preset_accent-"] * {
    color: #0b1620 !important;
  }
  /* The rest of the Button's preset vocabulary, all natively COLOURED: `success` is the solid
     #02D15C call CTA, `accentSecondary` a #cfedff fill with a #008AED label, `paySecondary` the
     #e9ddfd/#8c4fe8 Avito Pay lavender. Each keeps its hue on a tinted dark surface.
     `root_preset_accent` is NOT matched here: `[class*=]` would also catch
     `root_preset_accentSecondary`. Ad blocks ship the same soft-blue CTA under pure hashes, so the
     ad container's wrapper, whose only buttons ARE those CTAs, takes the same treatment. */
  button[class*="root_preset_success"] {
    background-color: #198049 !important;
    border-color: #198049 !important;
  }
  button[class*="root_preset_success"],
  button[class*="root_preset_success"] * {
    color: #fff !important;
  }
  [class*="root_preset_accentSecondary"],
  [class*="avito-ads-container"] button {
    background-color: #1d2c3a !important;
    border-color: #2f4a63 !important;
  }
  [class*="root_preset_accentSecondary"],
  [class*="root_preset_accentSecondary"] *,
  [class*="avito-ads-container"] button,
  [class*="avito-ads-container"] button * {
    color: #9fd0f5 !important;
  }
  [class*="root_preset_paySecondary"] {
    background-color: #2b2140 !important;
    border-color: #40325e !important;
  }
  [class*="root_preset_paySecondary"],
  [class*="root_preset_paySecondary"] * {
    color: #c3a3f5 !important;
  }
  /* Ad blocks also build "Подробнее" from the NEUTRAL `secondary` preset, not the soft-blue
     `accentSecondary` the container arm is written for, so an explicit preset must outrank the
     container: hence the (0,2,1) pairing. */
  [class*="avito-ads-container"] button[class*="root_preset_secondary"] {
    background-color: #262c35 !important;
    border-color: var(--av-border) !important;
  }
  [class*="avito-ads-container"] button[class*="root_preset_secondary"],
  [class*="avito-ads-container"] button[class*="root_preset_secondary"] * {
    color: var(--av-text-soft) !important;
  }
  /* The DS Button's DISABLED state is a `root_disabled` modifier (plus `aria-disabled`) on top of
     whatever preset the button has, natively the secondary's `#f2f1f0` under a `#a3a3a3` label: the
     region picker's untouched save CTA and the complaint dialog's "Продолжить" both ship it on the
     `accent` preset. Every preset arm above is (0,1,1) and paints it as a live CTA, so this block
     must follow them all; the descendant arm ties the presets' ink arms and wins on order. */
  button[class*="root_disabled"] {
    background-color: #262c35 !important;
    border-color: var(--av-border) !important;
  }
  button[class*="root_disabled"],
  button[class*="root_disabled"] * {
    color: var(--av-text-muted) !important;
  }
  /* DS BADGE. Both presets paint through `--module-badge-backgroundColor`. `root_preset_primary` is
     shared with the Button and the Spinner, so both properties read the badge's OWN tokens with a
     fallback: a Spinner leaves them unset and stays flat, a Badge resolves them. Redefining the sale
     token on the same element lands the pill on the theme's refined red. */
  /* A second Badge build ships pure hashes and no preset name. What both share is the wrapper the
     badge is anchored to, which carries the offset as an inline custom property and holds exactly one
     child. Match the property NAME only: the value is a per-instance px offset. */
  div[class*="root_preset_primary"],
  [style*="--module-badge-offset-x"] > div {
    --theme-semantics-components-badge-bg-sale: #c8323f;
    background-color: var(--module-badge-backgroundColor, transparent) !important;
    color: var(--module-badge-color, var(--av-text-soft)) !important;
  }
  /* The search / card reveal CTA is natively a SOFT light-blue button. The item-page primaries are
     promoted to the green call CTA below (same specificity, later wins). */
  [data-marker^="item-phone-button"] {
    background-color: #1d2c3a !important;
    border-color: #2f4a63 !important;
  }
  [data-marker^="item-phone-button"],
  [data-marker^="item-phone-button"] * {
    color: #9fd0f5 !important;
  }
  /* Primary brand-blue CTAs */
  [data-marker="search-form/submit-button"],
  [data-marker="top-rubricator/all-categories"],
  [data-marker="top-rubricator/all-categories-icon"],
  [data-marker$="/phone-button"],
  button[type="submit"] {
    background-color: var(--av-accent) !important;
    color: #0b1620 !important;
  }
  /* The item page pairs TWO solid primaries: call green and brand blue — the colour is the only
     thing separating a call from a message. Same green as the profile page's `call-button`. */
  [data-marker="item-phone-button/header"],
  [data-marker="item-phone-button/card"],
  [data-marker="item-phone-button/gallery"] {
    background-color: #198049 !important;
    border-color: #198049 !important;
  }
  [data-marker="item-phone-button/header"],
  [data-marker="item-phone-button/header"] *,
  [data-marker="item-phone-button/card"],
  [data-marker="item-phone-button/card"] *,
  [data-marker="item-phone-button/gallery"],
  [data-marker="item-phone-button/gallery"] * {
    color: #fff !important;
  }
  /* `messenger-button/link` is the same marker on BOTH surfaces: a solid brand-blue primary on the
     item page, a neutral `#f2f1f0` chip on cards. The card variant is keyed on its being a DS Button
     while the item page's is under pure hashes — keying on the preset modifier would not hold, that
     variant having shipped as both `root_preset_secondary` and `root_preset_overlay`. At (0,2,1) it
     beats the accent rule outright. */
  a[data-marker="messenger-button/link"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  a[data-marker="messenger-button/link"],
  a[data-marker="messenger-button/link"] * {
    color: #0b1620 !important;
  }
  a[class*="styles-module-root"][data-marker="messenger-button/link"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  a[class*="styles-module-root"][data-marker="messenger-button/link"],
  a[class*="styles-module-root"][data-marker="messenger-button/link"] * {
    color: var(--av-text-soft) !important;
  }
  /* The model/catalog page ships a THIRD build under pure hashes the DS-class arm cannot reach.
     Every card-embedded messenger CTA is a `[data-marker="item"]` descendant and is a secondary;
     only the item page's buy-box copy sits outside a card and stays the accent. The fill is the
     secondary preset's tone, not `--av-surface`: this CTA shows only on hover and the hover panel is
     itself `--av-surface`, so a surface chip would have no edge. */
  [data-marker="item"] a[data-marker="messenger-button/link"] {
    background-color: #262c35 !important;
    border-color: var(--av-border) !important;
  }
  [data-marker="item"] a[data-marker="messenger-button/link"],
  [data-marker="item"] a[data-marker="messenger-button/link"] * {
    color: var(--av-text-soft) !important;
  }

  /* The delivery CTAs are natively SOLID PURPLE `#965EEB`, the counterpart to the blue phone CTA.
     Their fill comes from a hashed CLASS, not an inline style, so no `[style*=]` badge rule reaches
     them. The prefix arm covers the `delivery-item-button-` family (the plain-text
     `delivery/landing` link has no `-button`); the lightbox's copy sits outside it, hence the `$=`
     arm. */
  [data-marker^="delivery-item-button"],
  [data-marker$="-delivery-button"] {
    background-color: #7d5bc4 !important;
    border-color: #7d5bc4 !important;
  }
  [data-marker^="delivery-item-button"],
  [data-marker^="delivery-item-button"] *,
  [data-marker$="-delivery-button"],
  [data-marker$="-delivery-button"] * {
    color: #fff !important;
  }

  /* Segmented filter controls: the SELECTED option */
  /* The search filters are radio groups whose pill is a SPAN next to a visually-hidden checked
     <input>. The generic button rule paints every pill `--av-surface` and the broad text rule every
     label `--av-text-soft`, so all options render IDENTICALLY and the active filter is invisible —
     no contrast or luminance check sees it, only a native diff.
     Two builds: the older puts the state on the sibling input's `:checked`, the newer on the pill
     itself as `wrapper_isChecked-<hash>`, which holds even where the pill is not an input's sibling.
     Match the modifier prefixes, never the hash: a rotated hash drops the unselected pills back to
     their native `#f2f1f0`. */
  input:checked + [class*="style-module-wrapper"],
  [class*="wrapper_isChecked"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  input:checked + [class*="style-module-wrapper"],
  input:checked + [class*="style-module-wrapper"] *,
  [class*="wrapper_isChecked"],
  [class*="wrapper_isChecked"] * {
    color: #0b1620 !important;
  }

  /* Installment-period selector (item buy-box) */
  /* The "рассрочка" period picker is `label > input[type=radio] + span` pills, natively white with a
     near-black checked one; `span` is deliberately outside the div-neutraliser. */
  [data-marker="installments-promoblock"] input[type="radio"] + span {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
    color: var(--av-text) !important;
  }
  [data-marker="installments-promoblock"] input:checked + span {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
    color: #0b1620 !important;
  }
  /* The upcoming payment segments are inline-styled SPANs under pure hashes, so the inline value is
     the only stable hook. Written against `background`, not `background-color`: Avito uses the
     shorthand here. */
  [style*="background: rgb(214, 214, 214)"],
  [style*="background:rgb(214, 214, 214)"],
  [style*="background:#D6D6D6"], [style*="background:#d6d6d6"] {
    background-color: var(--av-border) !important;
  }

  /* Item-page variant chips (condition / memory / …) */
  /* The item page's attribute switchers are `label > input + span` pills under a different class
     from the segmented filters above. Scoped to the container so the colour-swatch chips, which carry
     their hue on the pill, are untouched. */
  [data-marker="multi-items"] label > span {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [data-marker="multi-items"] label > span,
  [data-marker="multi-items"] label > span * {
    color: var(--av-text) !important;
  }
  [data-marker="multi-items"] label input:checked + span {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [data-marker="multi-items"] label input:checked + span,
  [data-marker="multi-items"] label input:checked + span * {
    color: #0b1620 !important;
  }

  /* Model / catalog page (…/catalog/<brand>/<model>/…/specs-…) */
  /* The model page's modification switcher is the multi-items pattern under a DIFFERENT hook, with
     no `multi-items` marker, and its checked pill's native `#141414` is the dimmest of the group,
     inverting the indicator. */
  [data-marker="model-card/modification-form"] label > span {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [data-marker="model-card/modification-form"] label > span,
  [data-marker="model-card/modification-form"] label > span * {
    color: var(--av-text) !important;
  }
  [data-marker="model-card/modification-form"] label input:checked + span {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [data-marker="model-card/modification-form"] label input:checked + span,
  [data-marker="model-card/modification-form"] label input:checked + span * {
    color: #0b1620 !important;
  }
  /* The same page's two CTAs are anchors under pure hashes, reached by neither the
     `styles-module-root` nor the `-button` arms. */
  [data-marker="model-card/mini-serp-2/button"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* `a[data-marker$="-button"]` (the text-link un-painter above) also matches
     `model-card/ui-button` at (0,1,1), so this arm must carry the `a` type too —
     the tie then breaks on source order. */
  a[data-marker="model-card/ui-button"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [data-marker="model-card/ui-button"],
  [data-marker="model-card/ui-button"] * {
    color: #0b1620 !important;
  }

  /* Item-page colour-variant swatches (inline-rgb solids) */
  /* Each colour option here is a 48x48 <div> whose hue is EITHER a `rect_*_96.png` background-IMAGE
     (metallics, which survive — the neutraliser only clears background-COLOR) OR an inline solid
     `background-color: rgb(...)`, which it flattens. Restore the inline hue verbatim; both `rgb()`
     spellings are listed for the reason the badge rules list them.
     Each hue must be named LITERALLY — nothing in CSS can re-apply an inline value an `!important`
     rule has beaten, so a hue missing here renders as an empty slot and a guessed literal is dead
     code. Harvest new ones from a filter rail's `color-circle-circle` swatches or the
     `"color":"#HEX"` entries in a search page's initial-state JSON: 14 hues in all, a rail showing
     only its category's subset. Gold and beige are solids; silver is the one metallic shipped as a
     PNG. */
  [data-marker="multi-item-image"] [style*="background-color: rgb(106, 54, 227)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(106, 54, 227)"] {
    background-color: rgb(106, 54, 227) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(41, 41, 41)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(41, 41, 41)"] {
    background-color: rgb(41, 41, 41) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 255, 255)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 255, 255)"] {
    background-color: rgb(255, 255, 255) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(28, 140, 56)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(28, 140, 56)"] {
    background-color: rgb(28, 140, 56) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(245, 64, 67)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(245, 64, 67)"] {
    background-color: rgb(245, 64, 67) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(50, 100, 250)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(50, 100, 250)"] {
    background-color: rgb(50, 100, 250) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(28, 191, 255)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(28, 191, 255)"] {
    background-color: rgb(28, 191, 255) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 228, 51)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 228, 51)"] {
    background-color: rgb(255, 228, 51) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 161, 234)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 161, 234)"] {
    background-color: rgb(255, 161, 234) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(156, 156, 156)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(156, 156, 156)"] {
    background-color: rgb(156, 156, 156) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(128, 92, 58)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(128, 92, 58)"] {
    background-color: rgb(128, 92, 58) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(199, 28, 59)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(199, 28, 59)"] {
    background-color: rgb(199, 28, 59) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(255, 176, 33)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(255, 176, 33)"] {
    background-color: rgb(255, 176, 33) !important;
  }
  [data-marker="multi-item-image"] [style*="background-color: rgb(206, 196, 173)"],
  [data-marker="multi-item-image"] [style*="background-color:rgb(206, 196, 173)"] {
    background-color: rgb(206, 196, 173) !important;
  }

  /* Text */
  /* The site hardcodes near-black text colours; force them light. */
  body, p, span, li, td, th, div, label, dd, dt, time, small, b, strong, em,
  h1, h2, h3, h4, h5, h6 {
    color: var(--av-text-soft) !important;
  }
  /* The business-hours status's inline `color: rgb(255, 97, 99)` is the only closed/open signal and
     the broad text rule's `!important` beats it, so the value is restated at the native hue. */
  [style*="color: rgb(255, 97, 99)"], [style*="color:rgb(255, 97, 99)"],
  [style*="color:#ff6163"], [style*="color:#FF6163"] {
    color: #ff6163 !important;
  }
  /* The DS field's validation message is a bare `error-<hash>` span whose only marking is that
     status red. The element is the span itself, so no descendant arm; the tag guard keeps the generic
     `error-` fragment off any block a build may name the same way. */
  span[class*="error-"] {
    color: #ff6163 !important;
  }
  /* In the SEO geo-links tab strip the inactive tab's inline blue is the ONLY thing saying it is
     clickable. The theme accent replaces it for the same reason `a` does. */
  [style*="color: rgb(0, 153, 247)"], [style*="color:rgb(0, 153, 247)"],
  [style*="color:#0099f7"], [style*="color:#0099F7"] {
    color: var(--av-accent) !important;
  }
  /* The discount-percentage label is a bare span, natively `#f71b47`, flattened by the broad span
     rule; the native red is under 4.5:1 on a card, so it takes one step lighter. */
  [data-marker="discount-value"],
  [data-marker="discount-value"] * {
    color: #ff5c78 !important;
  }
  /* Rating STARS are mask-image `<svg>`s painted by `background-color: currentColor`, so a star's
     colour IS its inherited `color` and the broad span rule greys it — invisible to any contrast or
     light-surface check. Scoped to the `filled` modifier so empty stars keep their muted state. */
  [class*="styles-module-star"] [class*="styles-module-filled"] {
    color: #ffb021 !important;
  }
  /* Newer builds of the same rating widget miss the `styles-module-filled` hook above. The widget
     declares its palette as custom properties on the rating root but paints the glyph through the
     span's inherited `color`, which the broad text rule takes.
     THREE builds are live, one arm each. `sellerRate` names the filled span with a PURE HASH —
     nothing but the hash separates it from an empty star. The others name it `filled-<hash>`: match
     the modifier PREFIX, keeping the trailing `-` so it anchors to the `<name>-<hash>` shape and not
     any class containing "filled". Every arm is scoped to the FILLED state, so a rotated hash leaves
     a star uninformative rather than gold on an empty one.
     The marker belongs to the CALL SITE, so each new embedding needs naming again, and every call
     site declares the palette as inline custom properties on the rating root — match that property
     NAME, never its value, which serialises with and without spaces. */
  [data-marker="sellerRate"] span[class*="_4da9fca36a8c49c9"],
  [data-marker^="seller-rating/rating-stars"] span[class*="_4da9fca36a8c49c9"],
  [data-marker="sellerRate"] span[class*="filled-"],
  [data-marker^="seller-rating/rating-stars"] span[class*="filled-"],
  [style*="--star-color-filled"] span[class*="_4da9fca36a8c49c9"],
  [style*="--star-color-filled"] span[class*="filled-"] {
    color: #ffb021 !important;
  }
  /* `[data-marker*="title"]` would be too loose: a bare `data-marker="title"` also sits on the
     notification banner's brand-blue "Подробнее" LINK, and this rule at (0,1,0) beats
     `a { color: accent }` at (0,0,1). Listing titles all carry `item-title`. */
  h1, h2, h3, h4, h5, h6,
  [class*="title"], [data-marker*="item-title"] {
    color: var(--av-text) !important;
  }

  /* Links / accent */
  a {
    color: var(--av-accent) !important;
  }
  a:hover {
    color: var(--av-accent-hover) !important;
  }
  /* Scoped to `item-title` for the same reason as the rule above — a bare `title` marker also names
     the notification banner's blue CTA link. */
  a[class*="title"], a[data-marker*="item-title"],
  [data-marker="item-title"] a, h3 a {
    color: var(--av-text) !important;
  }
  [data-marker="item-title"] a:hover, h3 a:hover {
    color: var(--av-accent-hover) !important;
  }
  /* The home grid's listing titles carry `data-marker="title"` (not `item-title`, which only search
     uses) and the DS `root_preset_black` modifier, whose name states the native colour, so keying off
     it is exact. */
  a[class*="root_preset_black"] {
    color: var(--av-text) !important;
  }
  a[class*="root_preset_black"]:hover {
    color: var(--av-accent-hover) !important;
  }
  /* The DS Link marks hover by COLOUR alone, and its label is a nested Text element that the broad
     text rule pins with `!important`, so `a:hover` alone moves nothing visible.
     The child combinator is load-bearing: a seller-name link wraps its whole rating widget, whose
     gold stars are painted through `color`, and a descendant selector would out-specify the star
     rule and blue every star on hover — only the label is ever a direct `p`/`span` child. The
     header's location link splits its label across two spans inside that `p`, reached under the
     direct `p` only. */
  a[class*="root_underlineOffset"]:hover > p,
  a[class*="root_underlineOffset"]:hover > span,
  a[class*="root_underlineOffset"]:hover > p span {
    color: var(--av-accent-hover) !important;
  }
  /* The `link-<hash>` variant reserves its underline as a transparent `border-bottom` and only tints
     it on hover, so the blanket border reset paints it a permanent grey AND pins that grey through
     the hover. */
  a[class*="link-"] {
    border-color: transparent !important;
  }
  a[class*="link-"]:hover {
    border-color: currentColor !important;
  }

  /* Text on coloured surfaces (must come after the broad text rule) */
  /* Keep labels readable on the re-painted chips, pills and primary buttons. */
  [style*="background-color: rgb(255, 64, 83)"],
  [style*="background-color: rgb(255, 64, 83)"] *,
  [style*="background-color: rgb(2, 209, 92)"],
  [style*="background-color: rgb(2, 209, 92)"] *,
  [style*="background-color: rgb(150, 94, 235)"],
  [style*="background-color: rgb(150, 94, 235)"] *,
  [style*="background-color: rgb(229, 9, 101)"],
  [style*="background-color: rgb(229, 9, 101)"] *,
  [style*="background-color:#FF4053"], [style*="background-color:#FF4053"] *,
  [style*="background-color:#02D15C"], [style*="background-color:#02D15C"] *,
  [style*="background-color:#965EEB"], [style*="background-color:#965EEB"] *,
  [style*="background-color:#E50965"], [style*="background-color:#E50965"] * {
    color: #fff !important;
  }
  [style*="background-color: rgb(0, 170, 255)"],
  [style*="background-color: rgb(0, 170, 255)"] *,
  [style*="background-color:#00AAFF"], [style*="background-color:#00AAFF"] * {
    color: #0b1620 !important;
  }
  [style*="background-color: rgb(204, 236, 255)"],
  [style*="background-color: rgb(204, 236, 255)"] *,
  [style*="background-color: rgb(207, 237, 255)"],
  [style*="background-color: rgb(207, 237, 255)"] *,
  [style*="background-color:#CCECFF"], [style*="background-color:#CCECFF"] *,
  [style*="background-color:#CFEDFF"], [style*="background-color:#CFEDFF"] * {
    color: #9fd0f5 !important;
  }
  /* Dark text only on the brand-blue CTAs. The item page's green call CTAs take white ink from
     their own rules above and must NOT be listed here — this block is later in source order and
     would win the tie. */
  [data-marker="search-form/submit-button"],
  [data-marker="search-form/submit-button"] *,
  [data-marker="top-rubricator/all-categories"],
  [data-marker="top-rubricator/all-categories"] *,
  [data-marker$="/phone-button"],
  [data-marker$="/phone-button"] * {
    color: #0b1620 !important;
  }
  /* "В корзину" is the DS `paySecondary` preset; the preset rule above restores the tinted fill and
     this keeps the purple label above 4.5:1 on it. */
  [data-marker="cart-actions/cart-button"],
  [data-marker="cart-actions/cart-button"] * {
    color: #a97cf0 !important;
  }
  /* `button[type="submit"]` is painted brand-blue by the button rules, but its label lives in a
     `<span>` the broad text rule paints light grey — ~2:1 on the blue. */
  button[type="submit"] * {
    color: #0b1620 !important;
  }
  /* The legacy error/404 template styles two anchors as brand-blue buttons with a white label, so
     `a { color: var(--av-accent) }` would leave brand-blue on brand-blue. */
  a.header-add-item-link, a.content-home-link {
    background-color: var(--av-accent) !important;
  }
  a.header-add-item-link, a.header-add-item-link *,
  a.content-home-link, a.content-home-link * {
    color: #0b1620 !important;
  }

  /* Inputs, selects, filter fields */
  [data-marker="search-form/suggest/input"],
  [data-marker="search-form"] input,
  input, textarea, select,
  [data-marker$="/multiselect-outline-input"],
  [data-marker$="-from"], [data-marker$="-to"],
  [class*="multiselect"], [class*="-input"], [class*="Input"] {
    background-color: var(--av-surface) !important;
    color: var(--av-text) !important;
    border-color: var(--av-border) !important;
  }
  /* The search field sits in a white wrapper — darken that too. */
  [data-marker="search-form/suggest"] {
    background-color: var(--av-surface) !important;
  }
  /* The DS Input draws its field box on the wrapping <label> and leaves the <input> transparent, so
     filling the input alone lights only the text run. `root_size-` with a HYPHEN is the Input's own
     size modifier — the switch/checkbox label spells it `root_size_`. The header search widget shares
     the `suggest-` name on a DIV that already has its own fill, so the tag guard is load-bearing. */
  label[class*="root_size-"],
  label[class*="suggest-"] {
    background-color: var(--av-surface) !important;
  }
  /* The header-search field and its submit button each sit on a full-size `::before` plate painting
     the brand ring — blue at rest, hard-coded WHITE while the suggest panel is open, and invisible to
     element-bg scans. The open-state modifier is a hash in both builds, so the hook is structural:
     the plates are the direct div children of the marker. */
  [data-marker="search-form"] > div::before {
    background-color: var(--av-accent) !important;
  }
  ::placeholder { color: var(--av-text-muted) !important; opacity: 1; }
  /* The price range fields have no `placeholder`: their "От" / "до" hints are `prefix-<hash>` SPANs
     the site mutes only while the field is EMPTY (a `root_empty-<hash>` class on the wrapping label,
     dropped on the first digit). The broad text rule lights them in both states. */
  [class*="root_empty-"] [class*="prefix-"],
  [class*="root_empty-"] [class*="postfix-"] {
    color: var(--av-text-muted) !important;
  }
  /* Every suggest-panel row leads with a 20x20 `<img>` of flat BLACK line art drawn for the white
     sheet. A raster is out of reach of `fill`/`color`, so flip the lightness; the set is monochrome
     (the "full_color" path name notwithstanding), so the invert cannot distort a hue. Scoped to the
     panel's only `<img>`. */
  [class*="itemIconImg"] {
    filter: invert(1);
  }
  /* The in-profile filters icon has two SVG paths with a hard `fill="black"` ATTRIBUTE, overriding
     the `<svg fill="currentColor">` above them. Neither scan sees it: the SVG bucket flags only
     near-WHITE fills, and the element's own `color` reads light. */
  [data-marker$="/filters_icon"] svg path {
    fill: var(--av-text) !important;
  }

  /* The generic input rule paints the auth popup's fields `--av-surface`, exactly the popup's own
     colour, so they sink to the base canvas instead. */
  [data-marker="auth-app/popup"] input {
    background-color: var(--av-bg) !important;
  }

  /* Checkbox / radio checked state */
  /* The real control is a DIV beside a visually-hidden <input>, its checked fill coming from a
     `--kitty-commonToggle-*` token. The tick/dot uses `fill: currentColor`, so it follows `color`.
     Scoped to checkbox/radio mode so switches keep their knob styling. */
  [class*="controlledInput_checked"] + [class*="toggle_mode_checkbox"],
  [class*="controlledInput_checked"] + [class*="toggle_mode_radio"] {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [class*="controlledInput_checked"] + [class*="toggle_mode_checkbox"],
  [class*="controlledInput_checked"] + [class*="toggle_mode_checkbox"] *,
  [class*="controlledInput_checked"] + [class*="toggle_mode_radio"],
  [class*="controlledInput_checked"] + [class*="toggle_mode_radio"] * {
    color: #0b1620 !important;
  }
  /* The item page's dialogs ship the same control under pure hashes, out of reach of the module-name
     hooks. The DS puts the role and `aria-checked` on the LABEL and paints the disc on the input's
     next sibling, so ARIA is the build-independent hook. Only the CHECKED fill is restored — the
     unchecked disc keeps the blanket border rule's ring. */
  [role="radio"][aria-checked="true"] input + div,
  [role="checkbox"][aria-checked="true"] input + div {
    background-color: var(--av-accent) !important;
    border-color: var(--av-accent) !important;
  }
  [role="radio"][aria-checked="true"] input + div,
  [role="radio"][aria-checked="true"] input + div *,
  [role="checkbox"][aria-checked="true"] input + div,
  [role="checkbox"][aria-checked="true"] input + div * {
    color: #0b1620 !important;
  }

  /* Switch (toggle) track */
  /* The switcher's track is natively light `#e3e2e1` off and near-black `#141414` on, the only thing
     distinguishing the states beyond a 20px knob shift. */
  [class*="toggle_mode_switcher"] {
    background-color: var(--av-border) !important;
  }
  [class*="controlledInput_checked"] + [class*="toggle_mode_switcher"] {
    background-color: var(--av-accent) !important;
  }

  /* Search results view-mode switcher (list / gallery / map) */
  /* The ACTIVE view is marked by colour alone. The active one is a DIV (greyed by the broad text
     rule) while the others are `<a>` (blued by `a { accent }`), so the indicator ends up INVERTED.
     The inactive icons are mask glyphs on `currentColor`; the active one ships an inline
     `--kitty-icon-color`, a hard black `background-color` no `color` rule can reach. */
  [data-marker^="view-change"] {
    color: var(--av-text-muted) !important;
  }
  [data-marker$="/icon-active"] {
    color: var(--av-accent) !important;
    background-color: var(--av-accent) !important;
  }

  /* Tab bars (seller profile: Главная / Объявления / Отзывы) */
  /* Natively transparent `<button>`s marking the current tab by TEXT COLOUR alone; the generic
     button rule pills them and `[class*="title"]` inks every label alike. The title arms are (0,2,0)
     so they outrank the generic title rule; the active arm ties them and wins on source order. */
  [class*="tab-button"] {
    background-color: transparent !important;
  }
  [class*="tab-button"],
  [class*="tab-button"] [class*="tab-button-title"] {
    color: var(--av-text-muted) !important;
  }
  [class*="tab-button_active"],
  [class*="tab-button_active"] [class*="tab-button-title"] {
    color: var(--av-accent) !important;
  }

  /* Floating surfaces (dropdowns, popovers, menus) */
  /* The DS Dropdown root is `styles-module-dropdown-` in one build and a bare `dropdown-` in the
     newer one; the trailing hyphen anchors the short spelling to the `<name>-<hash>` shape, and the
     `/dropdown` marker suffix reaches any call site that names its panel. */
  [data-marker="suggest/list/dropdown"],
  [data-marker$="/dropdown"],
  [class*="suggest-dropdownItems"],
  [class*="styles-module-dropdown"],
  [class*="styles-module-dropdownScrollWr"],
  [class*="dropdown-"],
  [class*="dropdownScrollWr"],
  [class*="styles-module-popup"],
  [class*="styles-module-popover"],
  [class*="styles-module-tooltip"],
  [class*="popup-popup"],
  [class*="popover-content"],
  [data-marker="overlay"] [role="listbox"],
  [role="listbox"], [role="menu"], [role="tooltip"], [role="dialog"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* `styles-module-tooltip` above also substring-matches the tooltip TRIGGER, an inline hint glyph
     rather than a surface. Only the panel is a surface. */
  [class*="tooltip-trigger"] {
    background-color: transparent !important;
  }
  /* `role="listbox"` is a floating-panel hook, but the DS List also hangs the role on IN-FLOW
     horizontal carousels. Orientation is the durable discriminator: a floating dropdown listbox is
     vertical. The ARIA arm is the general one — the item page's carousel has role and orientation
     but neither the DS class nor the marker. All three arms outrank the (0,1,0) panel arm. */
  [role="listbox"][aria-orientation="horizontal"],
  [role="listbox"][class*="_orientation_horizontal"],
  ul[data-marker$="/items-list"] {
    background-color: transparent !important;
  }
  /* Header nav fly-out menus are hashed absolutely-positioned panels; the stable hook is the
     nav-container wrapper. Each `li` holds exactly two child divs, TRIGGER then PANEL, so the
     adjacent-sibling combinator picks the panel alone — without it the natively transparent trigger
     takes a fill that reads as an active state. The fill belongs on that div's single CHILD: the
     panel is wider than its wrapper, offset 24px left and rounded, so a fill on the wrapper leaves a
     transparent strip down the left edge and a ledge above and below. */
  [class*="nav-container-HEADER"] li > div > div + div > div {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* The RUBRICATOR mega-menu's sheet is a natively WHITE trio of nested DIVs; painting the shared
     `content-root` prefix covers all three at once, opaque over opaque in one tone. No load-time scan
     sees it: the panel is portalled in on click. */
  /* The rebuilt menu drops the `new-rubricator-` prefix; the sheet is a `contentSheet-<hash>` div
     under the popup's marker. Painting the outer sheet is enough — everything inside it is
     transparent. */
  [class*="new-rubricator-content-root"],
  [data-marker="more-popup"] [class*="contentSheet"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* Its wrapper is the menu's backdrop, covered by the portal backdrop rule below. Inside, the
     root-category list marks the open subtree with a light fill and nothing else, so the `active`
     modifier is the only discriminator; the rebuilt menu shortens it to `active-<hash>`, whose
     trailing `-` anchors it to the `<name>-<hash>` shape while the marker scope keeps it inside this
     twelve-row list. */
  [data-marker^="top-rubricator/root-category"][class*="styles-module-active"],
  [data-marker^="top-rubricator/root-category"][class*="active-"] {
    background-color: #262c35 !important;
  }
  /* Its promo card is a `#cfedff` light-blue panel. Scoped to the open menu so the shared
     `background_color` class is untouched elsewhere. */
  [data-marker="more-popup"] [class*="background_color"] {
    background-color: #1d2c3a !important;
  }
  /* Third-party UX-survey card, `position: fixed`. Every node is a DIV under the `uxs-` namespace;
     the hashes rebuild but that prefix is the vendor namespace and cannot collide with Avito's own.
     Painting every node the same surface is equivalent to painting the card; the CTA is natively
     `#00aaff` and is promoted back out of that fill. */
  [class*="uxs-"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [class*="uxs-"] button {
    background-color: var(--av-accent) !important;
  }
  [class*="uxs-"] button,
  [class*="uxs-"] button * {
    color: #0b1620 !important;
  }
  /* The dismiss control is the widget's only `type="button"` (the submit CTA carries no `type`),
     bare chrome holding an `<svg>` with a hard `fill="#B5B8C2"`. Its `color` is reset so a build
     switching the glyph to `currentColor` still renders it light. */
  [class*="uxs-"] button[type="button"] {
    background-color: transparent !important;
  }
  [class*="uxs-"] button[type="button"],
  [class*="uxs-"] button[type="button"] * {
    color: var(--av-text-soft) !important;
  }
  /* The card's wordmark is an `<img>` of a black-on-transparent SVG and the watermark a mask glyph
     on its own background. An `<img>`'s pixels are out of reach of `fill`/`color`, so flip the
     lightness and rotate the hue back: the lettering whitens, the brand dots keep their colours. */
  [class*="uxs-"] img {
    background-color: transparent !important;
    filter: invert(1) hue-rotate(180deg);
  }
  [class*="uxs-"] a div {
    background-color: var(--av-text-muted) !important;
  }
  /* Map view (`?map=1`, "На карте"). The results rail is a natively WHITE panel; "Фильтры" slides a
     second white sheet over it and a third whitens the rest. All three must be opaque, and the names
     do not nest as substrings, so each is listed. `map-root` is the map's own canvas, visible where a
     tile has not painted.
     The rebuilt map view is pure hashes but marks the two containers that matter; inside the side
     block, `fullHeight-` is the rail and `left-` the filter drawer, both far too generic to use
     unscoped, hence the marker prefix. The drawer must be opaque in its own right — it stacks ON the
     rail. */
  [class*="side-block-wrapper"],
  [class*="side-block-overlay-wrapper"],
  [class*="side-block-disabled"],
  [data-marker="map-full/side-block"] [class*="fullHeight-"],
  [data-marker="map-full/side-block"] [class*="left-"] {
    background-color: var(--av-surface) !important;
  }
  [class*="map-root"],
  [data-marker="map-view"] {
    background-color: var(--av-bg) !important;
  }
  /* While the filter drawer is open a `disabled-<hash>` sibling veils the rail: a white plate the
     site fades to 0.8, which the neutraliser wipes. The drawer is narrower than the rail, so the
     uncovered strip must dim with it. The tag guard keeps the fragment off any disabled button. */
  [data-marker="map-full/side-block"] div[class*="disabled-"] {
    background-color: var(--av-surface) !important;
  }
  /* The seller profile's "Адрес" map floats a natively white address card over the Yandex tiles, and
     the light body ink would land on the light raster — which no scan sees, the tiles being an image
     rather than a background. */
  [class*="Geo-module-wrapper"] [class*="Card-module-container"] {
    background-color: var(--av-surface) !important;
  }
  /* The rail's contact row ends in a scroll-fade mask whose `#f5f5f5` stops live in a
     background-IMAGE, layering over any background-color. It is `visibility: hidden` until the row
     overflows, so no load-time element-bg scan sees it lit. */
  [class*="contacts__overflow"] {
    background-image: none !important;
  }
  /* Cookie-consent toast (bottom-centre, z-index 12000): a DIV-based floating "kitty toastBar". */
  [data-marker="cookie-consent"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  /* Modal backdrop scrim, painted with `--kitty-backdrop-background` on a DIV. Only the
     `<name>/overlay` markers are backdrops; the bare `overlay` marker wraps dropdown listboxes and
     must stay transparent. */
  [data-marker$="/overlay"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  /* Portalled backdrops with no marker of their own, under pure hashes; `role="region"` is the
     stable hook. The child combinators are load-bearing: the mega-menu's own inner panel carries the
     same role several levels deeper, and a descendant selector at (0,2,0) would beat the
     rubricator-sheet surface above and wash the open menu black. Only a backdrop sits two levels
     under the portal container. */
  [data-marker="portals-container"] > div > [role="region"] {
    background-color: rgba(0, 0, 0, 0.4) !important;
  }
  /* Suggestion / menu rows stay readable on the panel. */
  [data-marker="suggest/list/custom-option"],
  [data-marker="suggest/list/custom-option"] * {
    color: var(--av-text-soft) !important;
  }
  [data-marker="suggest/list/custom-option"]:hover {
    background-color: var(--av-surface-2) !important;
  }
  /* The popover nub is a rotated DIV whose fill is its `background-color`; without it the `*` border
     rule outlines an empty box. Match the panel it belongs to. */
  [class*="styles-module-point-"],
  [class*="styles-module-point_"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-surface) !important;
  }
  /* The photo lightbox's backdrop lives on two hashed, marker-less DIVs whose only ancestor hook is
     the unnamed portal node. A parent-selector rule would reach it but is stripped from the
     userstyles.org build, so the scrim is a fixed `::before` on the one marker'd descendant:
     `position:fixed` sizes it to the viewport, `z-index:-1` drops it behind the gallery chrome while
     staying in the portal's stacking context. */
  [data-marker="extended-gallery/frame-wrapper"]::before {
    content: "";
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: -1;
    background-color: rgba(0, 0, 0, 0.85) !important;
  }
  /* The rebuilt lightbox is a solid WHITE full-viewport sheet (`position:fixed`, z-index 1000) under
     pure hashes, portalled as a direct child of the gallery marker. Its sibling, the inline slider
     wrapper, is natively transparent, so the canvas tone is invisible on it at rest. */
  [data-marker="item-view/main-gallery"] > div {
    background-color: var(--av-bg) !important;
  }

  /* Dark scrims over photos (erased by the div-neutraliser) */
  /* Avito floats white icons and labels directly on listing photos and relies on a translucent BLACK
     pill behind each one for legibility (values from the site's own stylesheet). Keep the labels
     white. */
  [class*="styles-galleryBadge"],
  [class*="photo-slider-item-more"],
  [class*="badge-reserved"],
  [class*="badge-viewed"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  [class*="photo-slider-counter"],
  [class*="custom-badge-module-badge"],
  [class*="delivery-badge-module-deliveryBadge"],
  [class*="favorite-icon-box-module-iconBox"] {
    background-color: rgba(0, 0, 0, 0.45) !important;
  }
  [class*="photo-slider-item-more"],
  [class*="photo-slider-item-more"] *,
  [class*="photo-slider-counter"],
  [class*="badge-reserved"], [class*="badge-reserved"] *,
  [class*="badge-viewed"], [class*="badge-viewed"] * {
    color: #fff !important;
  }

  /* Ad disclosure */
  /* The "Реклама" tag is the legally required ad marker, natively a translucent WHITE chip with black
     text over the creative. A translucent BLACK chip with white text reads on any creative. */
  [data-marker="adv-badge-tag"] {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }
  [data-marker="adv-badge-tag"],
  [data-marker="adv-badge-tag"] * {
    color: #fff !important;
  }
  /* Brand-lift survey widget (Buzzoola, in a same-origin iframe) */
  /* The survey renders inside an iframe whose `location.href` is the avito page itself, so this
     domain block applies to it. Its step tracks are bare `<span>`s, outside the div-neutraliser by
     design. The `:not(.active)` guard is load-bearing: the widget paints the completed step's blue
     without `!important`, so an unguarded arm would take the progress fill with it. */
  .buzz_wrapper .progress__items span:not(.active) {
    background-color: var(--av-border) !important;
  }

  /* Design-system Banner */
  /* The Banner paints its card on a child layer (`background_color-<hash>`, prefixed
     `styles-module-` in the older build, so the arms hook the shared substring) whose fill is
     `var(--kitty-banner-backgroundColor)`, a token set by the preset class on the Banner ROOT — no
     `[style*=]` or literal-colour selector can reach it.
     The preset vocabulary is eight names, each a semantic bg token, so each keeps its hue;
     `beige`/`warmGray`/`white` are the neutrals.
     `background-image` must be cleared on the same layer: a caller can hand the card an inline stack
     of pastel `radial-gradient`s, which layers over any background-COLOR. */
  [class*="root_preset_blue"] [class*="background_color"] {
    background-color: #1d2c3a !important;
    background-image: none !important;
    border-color: #2f4a63 !important;
  }
  [class*="root_preset_green"] [class*="background_color"] {
    background-color: #16291d !important;
    background-image: none !important;
    border-color: #24452e !important;
  }
  [class*="root_preset_red"] [class*="background_color"] {
    background-color: #2e1a1d !important;
    background-image: none !important;
    border-color: #4a2a2f !important;
  }
  [class*="root_preset_orange"] [class*="background_color"] {
    background-color: #2a2116 !important;
    background-image: none !important;
    border-color: #3d3120 !important;
  }
  [class*="root_preset_violet"] [class*="background_color"] {
    background-color: #2b2140 !important;
    background-image: none !important;
    border-color: #40325e !important;
  }
  [class*="root_preset_beige"] [class*="background_color"],
  [class*="root_preset_warmGray"] [class*="background_color"],
  [class*="root_preset_white"] [class*="background_color"] {
    background-color: var(--av-surface) !important;
    background-image: none !important;
    border-color: var(--av-border) !important;
  }
  /* The Beduin Gradient component (promo strips) paints a pastel `linear-gradient` as its
     background-IMAGE, fed by an inline `--beduin-gradient`; the div-neutraliser only clears
     background-COLOR. Both the component class and the token are matched so either spelling reaches
     it. */
  [class*="Gradient-module-root"],
  [style*="--beduin-gradient"] {
    background-image: none !important;
    background-color: var(--av-surface) !important;
  }
  /* Partner promo card on the item page: a soft-red `#ffe0e0` panel whose fill arrives as an inline
     `background:` SHORTHAND on a hash-classed div, so no class hook and no `background-color:`
     selector reaches it. Both `rgb()` spellings and both hex cases are listed. */
  [style*="background: rgb(255, 224, 224)"],
  [style*="background:rgb(255, 224, 224)"],
  [style*="background:#FFE0E0"], [style*="background:#ffe0e0"] {
    background-color: #2e1a1d !important;
    border-color: #4a2a2f !important;
  }
  /* The item page's "Скидки каждый день" banner is the same shape one hue over: a mint `#adf0d1` card
     painted through an inline `background:` shorthand on a hash-classed div. */
  [style*="background: rgb(173, 240, 209)"],
  [style*="background:rgb(173, 240, 209)"],
  [style*="background:#ADF0D1"], [style*="background:#adf0d1"] {
    background-color: #16291d !important;
    border-color: #24452e !important;
  }

  /* Model-rating badge (item page) */
  /* The green `#00c257` score pill is a hashed DIV the neutraliser flattens; its only stable hook is
     the `rating-and-reviews` marker two levels up. */
  [data-marker="rating-and-reviews"] > div > div:first-child > div,
  [data-marker="rating-and-reviews"] > div > div:first-child > div * {
    color: #fff !important;
  }
  [data-marker="rating-and-reviews"] > div > div:first-child > div {
    background-color: #198049 !important;
  }
  /* The review-count label is the LINK to the model's reviews, natively the rating green `#00a34c`,
     but a bare SPAN, so the broad text rule beats the anchor. Lift the green rather than blueing it;
     the score inside the pill stays white, the rule above being more specific. */
  [data-marker="rating-and-reviews"] span {
    color: #57c98a !important;
  }
  /* The MODEL / catalog page shows the same score-and-reviews block under its own marker, where both
     halves are lost: the link flattens to body grey and the neutraliser wipes the pill's fill. */
  [data-marker="model-card/common-info/rating"] span {
    color: #57c98a !important;
  }
  /* That pill's fill comes from an INLINE design token, so no
     `[style*="rgb(...)"]`/`[style*="#hex"]` selector could reach it — the token NAME is the hook.
     The rate palette is a five-step SCALE; collapsing it to one tone would make every rating look
     the same, so each step is named and refined to clear 4.5:1 against the white label. Listed after
     the link rule so the score stays white (equal specificity, later wins). */
  [style*="--theme-semantics-components-rate-bg-excellent"] {
    background-color: #198049 !important;
  }
  [style*="--theme-semantics-components-rate-bg-good"] {
    background-color: #4b7f10 !important;
  }
  [style*="--theme-semantics-components-rate-bg-medium"] {
    background-color: #8a5a00 !important;
  }
  [style*="--theme-semantics-components-rate-bg-low"] {
    background-color: #c8323f !important;
  }
  [style*="--theme-semantics-components-rate-bg-none"] {
    background-color: #4a4f57 !important;
  }
  [style*="--theme-semantics-components-rate-bg-"],
  [style*="--theme-semantics-components-rate-bg-"] span {
    color: #fff !important;
  }

  /* Pagination current page */
  /* The current page is natively a near-black `#141414` pill; restoring that colour would only trade
     one invisible indicator for another on a dark canvas, so it takes the accent. */
  [data-marker^="pagination-button"][aria-current="page"] {
    background-color: var(--av-accent) !important;
  }
  /* The digit lives in a nested span the broad text rule would otherwise grey. */
  [data-marker^="pagination-button"][aria-current="page"],
  [data-marker^="pagination-button"][aria-current="page"] * {
    color: #0b1620 !important;
  }

  /* Buttons */
  [data-marker="search-form/submit-button"],
  button[type="submit"] {
    background-color: var(--av-accent) !important;
    color: #0b1620 !important;
  }

  /* Hover feedback on painted controls */
  /* The design system marks hover by swapping a background token, and every fill this theme paints
     is `!important`, so that swap loses the cascade on every control at once. A `brightness()` lift
     replaces per-variant hover fills because the fill a control ends up with depends on which rule
     above won it, and a filter derives the hover tone from what is actually painted; it also cannot
     invent a surface on a natively bare control.
     Excluded: `filter` makes an element the containing block for its `position:fixed` descendants,
     so lifting the fixed title bar's favourite button would drag that bar's background pseudo onto
     the button's own box. */
  button:hover,
  a[class*="styles-module-root"]:hover,
  [class*="style-module-wrapper"]:hover,
  [class*="wrapper_variant_"]:hover {
    filter: brightness(1.3);
  }
  .js-item-view-title-info [data-marker="item-view/favorite-button"]:hover {
    filter: none;
  }
  /* Pagination page numbers are natively bare and mark hover with a grey pill, so a brightness lift
     has nothing to act on. The current page carries the accent and is a `<span>`, so only the other
     pages match here. */
  [data-marker^="pagination-button"] a:hover {
    background-color: var(--av-surface) !important;
  }

  /* Search-result card hover highlight (pseudo-element panels) */
  /* On card hover Avito paints a full-card light-grey `::before` backdrop plus a light halo behind
     the action buttons (a box-shadow glow on another `::before`) — both invisible to element-bg
     scans. Classes are hashed, so hook the stable `iva-item-` prefixes. */
  /* The model/catalog page ships the same hover panel under pure hashes; every card carrying it is
     a `[data-marker="item"]` on both surfaces. The pseudo only exists on hover, so painting it
     unconditionally cannot show a surface on a resting card. */
  /* The search grid builds that action slot from `actions-<hash>` / `actionsRedesign-<hash>` rather
     than `iva-item-actions`. Unlike the `iva-` panel this one exists at rest (an
     `actionsVisible-<hash>` state class, not `:hover`). */
  /* The model page builds the same slot under pure hashes with no `actions` name, so the last arm
     reaches it by structure: it is the only `div::before` inside a card that paints a background
     (the other pseudos are `::after` photo veils). The card's own `::before` has `content: none` at
     rest and never masks this one. */
  [class*="iva-item-redesign"]:hover::before,
  [class*="iva-item-redesign"]:hover [class*="iva-item-actions"]::before,
  [class*="iva-item-actions"]::before,
  [class*="actionsRedesign"]::before,
  [data-marker="item"]::before,
  [data-marker="item"] div::before {
    background-color: var(--av-surface) !important;
    box-shadow: none !important;
  }

  /* Carousel scroll-arrow buttons (SVG-disc, audit-blind) */
  /* The recommendation carousels draw their scroll buttons as an SVG `<rect fill=#fff>` disc with a
     black `<path>` arrow, and element-bg scans miss SVG fills. The hub rails' copy ships the OPPOSITE
     polarity, so the pair is normalised in both directions. */
  [data-marker$="/scroll-button-back"] svg rect,
  [data-marker$="/scroll-button-forward"] svg rect,
  button[class*="scrollButton"] svg rect {
    fill: var(--av-surface) !important;
  }
  [data-marker$="/scroll-button-back"] svg path,
  [data-marker$="/scroll-button-forward"] svg path,
  button[class*="scrollButton"] svg path {
    fill: var(--av-text) !important;
  }
  /* The item gallery's prev/next disc is white NATIVELY and holds a DS mask icon painted by its
     `background-color`, which follows `color` — so the broad text rule lightens the arrow into its
     own white disc. Pin the glyph dark; the disc stays white. `arrowback`/`arrowforward` belong to
     this control alone (breadcrumb chevrons are `arrowright`/`arrowforwardios`), and the `aria-label`
     guard keeps the rule on the labelled disc. */
  [aria-label] > [data-inline-icon] > svg[data-icon-name="arrowback"],
  [aria-label] > [data-inline-icon] > svg[data-icon-name="arrowforward"] {
    background-color: #0b1620 !important;
  }

  /* Gallery thumbnail strip: the SELECTED photo */
  /* Both strips mark the current photo with a brand-blue `::after` ring and nothing else, which the
     blanket `*::after` border reset collapses. The pseudo has `content: none` on unselected
     thumbnails, so painting it unconditionally cannot ring them. */
  [data-marker="image-preview/item"]::after,
  [data-marker="extended-image-preview/item"]::after {
    border-color: var(--av-accent) !important;
  }

  /* Favorite (add-to-wishlist) heart outline (SVG stroke, audit-blind) */
  /* The un-favourited heart is an SVG whose path has NO fill (`fill:none`) and a hard-coded black
     `stroke`; both the element-bg and the white-fill SVG scans miss a stroke-only black icon. The
     favourited state uses a separate filled/red icon and is untouched. */
  [data-marker="favorites-add"] svg path,
  [data-marker="item-view/favorite-button"] svg path,
  [class*="favoritesOutlineIcon"] path {
    stroke: var(--av-text-muted) !important;
  }

  /* Category-hub landing tiles & cards (e.g. /all/bytovaya_elektronika) */
  /* Category HUB pages render their showcase surfaces as hashed `<a>` elements, which the div-only
     neutraliser never touches, so they keep a hard light-grey fill: rubricator tiles, lazy
     product-image placeholders, search-history chips. */
  /* The rubricator tile was rebuilt as `gridItem-<hash>`, out of the class arm's reach; its marker is
     the durable hook. Natively the label is BLACK body text, not a link, so the blanket `a` accent has
     to come back off it. */
  /* The employer profile builds the same idea from a `Categorizer-module-item` anchor whose fill
     arrives from a palette-named sibling class, so the component class covers every tone variant at
     once. Its illustration is a transparent-backed PNG sized `cover`, so a colour override leaves the
     artwork intact. */
  [class*="visual-rubricator-gridItem"],
  [class*="search-history-widget-item"],
  [class*="category-block-img__placeholder"],
  [class*="Categorizer-module-item"],
  [data-marker^="visual-rubricator/block"] {
    background-color: var(--av-surface) !important;
    border-color: var(--av-border) !important;
  }
  [data-marker^="visual-rubricator/block"],
  [data-marker^="visual-rubricator/block"] * {
    color: var(--av-text) !important;
  }
  /* One tile per rail is promoted with an inline `background:#cfedff`, the only thing marking it as
     the featured entry; the arm has to out-specify the marker rule above, hence the doubled attribute
     selector. All three serialisations are listed — Avito emits lower-case hex, upper-case hex and
     spaced `rgb()` depending on the render path, and attribute matching is case-SENSITIVE. */
  [data-marker^="visual-rubricator/block"][style*="background:#cfedff"],
  [data-marker^="visual-rubricator/block"][style*="background:#CFEDFF"],
  [data-marker^="visual-rubricator/block"][style*="background: rgb(207, 237, 255)"] {
    background-color: #1d2c3a !important;
  }
  /* One tile per grid is the FEATURED one, its highlight an inline soft-blue `background:` shorthand
     the rule above would flatten. Scoped to the tile class — the search rail's colour swatches spell
     their hue the same way and must keep it verbatim. */
  [class*="visual-rubricator-gridItem"][style*="background:#cfedff"],
  [class*="visual-rubricator-gridItem"][style*="background:#CFEDFF"],
  [class*="visual-rubricator-gridItem"][style*="background: rgb(207, 237, 255)"],
  [class*="visual-rubricator-gridItem"][style*="background:rgb(207, 237, 255)"] {
    background-color: #1d2c3a !important;
    border-color: #2f4a63 !important;
  }

  /* The stories-rail scroll arrow is an empty DIV whose glyph is a background-IMAGE (a single
     `stroke="black"` path), which the neutraliser does not clear and no `color`/`fill` rule can reach.
     The asset is monochrome, so inverting its lightness cannot distort a hue. */
  [class*="story-previewer-arrow"] {
    filter: invert(1);
  }

  /* Loading skeletons */
  /* Result-list re-fetches swap in `placeholder-one-...` blocks whose bars are a mid-grey SVG
     served as a background-IMAGE, which the neutraliser does not clear — and no scan sees it: the
     element background is transparent and the grey is under the near-white threshold. */
  [class*="placeholder-one"] {
    opacity: 0.25;
  }
  /* The buyer-pages micro-frontend draws its hydration skeletons with a near-white SVG served as a
     background-IMAGE, which the neutraliser does not clear.
     `opacity` is not available as the dimmer: their pulse ANIMATES opacity, so an unimportant value
     never applies and an important one kills the pulse. The artwork is achromatic, so inverting its
     lightness cannot shift a hue, and 0.86 lands #F5F5F5 on ~#2b2b2b.
     The grid skeleton is a hash-only twin of the REAL recommendations grid: the real one carries
     `id="bx_recommendations"` and its cards as children, so both guards are what keeps this filter
     off live listing photos. */
  div[class*="styles-compactGrid-"]:not([id]):empty,
  div[class*="advert-mimicry-block-skeleton"],
  div[class*="placeholder-loading"] {
    filter: invert(0.86);
  }

  /* Price (semantic, kept prominent and light) */
  [data-marker="item-price"],
  [data-marker="item-price-value"],
  [data-marker="item-view/item-price"],
  [itemprop="price"] {
    color: var(--av-text) !important;
  }
  /* Sellers can PAY to highlight a price. The yellow swash is a `background-image` on an EMPTY,
     absolutely positioned sibling whose own `background-color` is `transparent`, so the element-bg
     audit sees nothing while near-white text sits on it at 1.16:1. Keep the swash — it is the paid
     feature — and re-ink the text. The STATE lives on the price's parent, reached by the shared
     `highlightRedesign` substring; the swash div holds no text, so scoping to `yellowHighlight` would
     match nothing. */
  [class*="highlightRedesign"],
  [class*="highlightRedesign"] * {
    color: #0b1620 !important;
    -webkit-text-fill-color: #0b1620 !important;
  }

  /* Footer */
  /* Only the legacy error/404 template ships a real `<footer>`, and there it IS the full-width page
     footer, so it takes the header tone.
     The modern template has no `<footer>`: the marker is just the 1200px CONTENT COLUMN, and the
     full-width band around it is a wrapper under pure hashes, so painting the marker stamps a
     hard-edged slab into the middle of the page. The band is unreachable and natively only a 3% step
     off the page, with no meaningful dark counterpart, so the column stays on the canvas. The `*=`
     arm carries the link ink only and must not carry a fill — it also matches every descendant
     marker. */
  footer {
    background-color: var(--av-header) !important;
    border-color: var(--av-border) !important;
  }
  footer a, [data-marker*="footer"] a {
    color: var(--av-text-soft) !important;
  }
  /* The page footer is a `<div data-marker="footer">`; every semantic `<footer>` inside a dialog is
     a COMPONENT action row, natively transparent. The bare arm has to stay — a `<footer>` is outside
     the div-neutraliser, so dropping it would let a natively light one through. */
  [role="dialog"] footer {
    background-color: transparent !important;
  }
}
